<script setup>
import {ref,computed,watch,inject} from 'vue'
const props=defineProps({modelValue:Boolean,domain:Object,kind:String,existing:Object})
const emit=defineEmits(['update:modelValue','saved'])
const repo=inject('repository'),notify=inject('notify'),form=ref({connection:{},mappings:[]}),error=ref(''),saving=ref(false),sample=ref(''),preview=ref(null),previewError=ref('')
const transformOptions=[['identity','保持原值'],['string','转为文本'],['number','转为数字'],['boolean','转为布尔'],['datetime','转为日期时间']].map(([value,title])=>({value,title}))
const fields=computed(()=>props.domain&&form.value.target?props.domain.sources.schema(form.value.target):[])
const catalog=computed(()=>props.domain?.sources.catalog().map(t=>({value:t.id,title:t.name+' · '+t.id}))||[])
watch(()=>props.modelValue,opened=>{if(opened){form.value=props.existing?JSON.parse(JSON.stringify(props.existing)):{name:'',kind:props.kind,scope:'internal',target:'surgeries',enabled:false,connection:props.kind==='api'?{url:'',method:'GET',responsePath:'',credentialRef:''}:{engine:'PostgreSQL',host:'',port:5432,database:'',schema:'',table:'',username:'',credentialRef:''},mappings:[]};error.value='';sample.value='';preview.value=null;previewError.value=''}})
watch([form,sample],()=>{preview.value=null;previewError.value=''},{deep:true})
function targetChanged(){form.value.mappings=[]}
function addMapping(){const field=fields.value.find(f=>!form.value.mappings.some(m=>m.internal===f.name));if(field)form.value.mappings.push({external:'',internal:field.name,transform:'identity',required:false})}
function runPreview(){preview.value=null;previewError.value='';try{if(sample.value.length>100000)throw Error('样例 JSON 最多 100000 字符');let parsed;try{parsed=JSON.parse(sample.value)}catch{throw Error('样例不是有效 JSON，请检查括号、引号和逗号')}preview.value=props.domain.sources.preview(form.value,parsed)}catch(e){previewError.value=e.message}}
async function save(){saving.value=true;error.value='';try{await repo.saveBinding(form.value);notify('绑定配置已保存，实际连接服务尚未接入');emit('saved');emit('update:modelValue',false)}catch(e){error.value=e.message}finally{saving.value=false}}
</script>
<template><VDialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" max-width="1100" scrollable><VCard class="domain-dialog"><div class="dialog-heading"><div><span class="eyebrow">数据源配置 · 本地保存</span><h2>{{existing?'编辑':'新建'}}{{kind==='api'?'接口':'数据库'}}绑定</h2></div><VBtn icon="tabler-x" color="secondary" variant="text" aria-label="关闭绑定配置" @click="emit('update:modelValue',false)"/></div><VDivider/><VCardText><VAlert type="info" variant="tonal" class="mb-6">凭据只填写引用标识。配置启用不表示已连接；实际接口调用、数据库连接及同步需后端接入。</VAlert><div class="form-grid"><div class="field"><label>数据源名称</label><VTextField v-model="form.name" maxlength="60" counter="60" placeholder="例如：院内手麻系统" aria-label="数据源名称"/></div><div class="field"><label>来源范围</label><VSelect v-model="form.scope" :items="[{value:'internal',title:'院内系统'},{value:'external',title:'院外系统'}]"/></div><div class="field"><label>内部目标表</label><VSelect v-model="form.target" :items="catalog" @update:model-value="targetChanged" aria-label="内部目标表"/></div><div class="field"><label>配置状态</label><VSelect v-model="form.enabled" :items="[{value:false,title:'停用'},{value:true,title:'启用（连接服务待接入）'}]"/></div></div>
<h3 class="subheading mb-4">{{kind==='api'?'接口配置':'数据库配置'}}</h3><div class="form-grid"><template v-if="kind==='api'"><div class="field"><label>接口地址</label><VTextField v-model="form.connection.url" maxlength="250" placeholder="https://his.example.org/api/surgeries" aria-label="接口地址"/></div><div class="field"><label>请求方法</label><VSelect v-model="form.connection.method" :items="['GET','POST']"/></div><div class="field"><label>响应数据路径（选填）</label><VTextField v-model="form.connection.responsePath" maxlength="250" placeholder="例如：data.records，空表示根节点" aria-label="响应数据路径"/></div></template><template v-else><div class="field"><label>数据库类型</label><VSelect v-model="form.connection.engine" :items="['PostgreSQL','MySQL','SQL Server','Oracle']"/></div><div class="field"><label>主机地址</label><VTextField v-model="form.connection.host" maxlength="250" placeholder="db.hospital.local" aria-label="主机地址"/></div><div class="field"><label>端口</label><VTextField v-model.number="form.connection.port" type="number" min="1" max="65535" aria-label="端口"/></div><div v-for="item in [['database','数据库 / 服务名'],['schema','Schema（选填）'],['table','外部表 / 视图'],['username','连接用户（选填）']]" :key="item[0]" class="field"><label>{{item[1]}}</label><VTextField v-model="form.connection[item[0]]" maxlength="250" :aria-label="item[1]"/></div></template><div class="field"><label>凭据引用（选填）</label><VTextField v-model="form.connection.credentialRef" maxlength="250" placeholder="例如：hospital/his-readonly" aria-label="凭据引用"/></div></div>
<div class="inline-actions mb-2"><h3 class="subheading">字段映射</h3><VSpacer/><VBtn variant="tonal" size="small" prepend-icon="tabler-plus" :disabled="form.mappings.length>=fields.length" @click="addMapping">添加映射</VBtn></div><p class="caption muted mb-4">外部字段 → 内部字段；支持点路径和类型转换。切换内部目标表会清空当前映射。</p><div class="scroll-table"><VTable class="mapping-table"><thead><tr><th>外部字段 / 点路径</th><th>内部字段</th><th>转换</th><th>必填</th><th>操作</th></tr></thead><tbody><tr v-for="(m,i) in form.mappings" :key="i"><td><VTextField v-model="m.external" maxlength="150" placeholder="operation_id" :aria-label="'外部字段 '+(i+1)"/></td><td><VSelect v-model="m.internal" :items="fields.map(f=>({value:f.name,title:f.name+' ('+f.type+')'}))" :aria-label="'内部字段 '+(i+1)"/></td><td><VSelect v-model="m.transform" :items="transformOptions" :aria-label="'转换方式 '+(i+1)"/></td><td><VCheckbox v-model="m.required" :aria-label="'字段必填 '+(i+1)" hide-details/></td><td><VBtn variant="text" color="error" :aria-label="'删除映射 '+(i+1)" @click="form.mappings.splice(i,1)">删除</VBtn></td></tr><tr v-if="!form.mappings.length"><td colspan="5" class="text-center muted">尚未配置字段映射，请添加至少一条。</td></tr></tbody></VTable></div>
<VExpansionPanels variant="accordion" class="my-5"><VExpansionPanel title="样例映射预览"><VExpansionPanelText><p class="caption muted mb-3">粘贴接口响应 JSON 或数据库结果行 / 数组，仅在本机预览，不写入内部数据表。最多 100 条。</p><VTextarea v-model="sample" rows="6" maxlength="100000" placeholder='{"data":{"records":[{"operation_id":"OP001"}]}}' aria-label="样例JSON"/><VBtn variant="tonal" class="my-3" @click="runPreview">预览映射结果</VBtn><VAlert v-if="previewError" type="error" variant="tonal" role="alert">{{previewError}}</VAlert><template v-if="preview"><VAlert :type="preview.errors.length?'warning':'success'" variant="tonal" class="mb-3">已生成 {{preview.records.length}} 条预览 · {{preview.errors.length}} 项错误。预览不会检查真实连接。</VAlert><pre class="json-view" role="status">{{JSON.stringify(preview,null,2)}}</pre></template></VExpansionPanelText></VExpansionPanel></VExpansionPanels><VAlert v-if="error" type="error" variant="tonal" role="alert">{{error}}</VAlert></VCardText><VDivider/><VCardActions><VSpacer/><VBtn color="secondary" variant="text" @click="emit('update:modelValue',false)">取消</VBtn><VBtn variant="flat" :loading="saving" @click="save">保存绑定配置</VBtn></VCardActions></VCard></VDialog></template>
<style scoped>.mapping-table{min-width:840px}.mapping-table th:nth-child(1){width:26%}.mapping-table th:nth-child(2){width:28%}.mapping-table th:nth-child(3){width:20%}</style>
